import time
import unicodedata
from urllib.parse import urlsplit

import requests
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry
import xmltodict


# Unicode normalization

def unicode_normalize(s):
    s = unicodedata.normalize("NFD", s)
    s = s.casefold()
    return unicodedata.normalize("NFD", s)


def unicode_collapse(s: str) -> str:
    """Returns s with accents removed and case folded, in canonical (NFC) form,
    so strings that differ only in accents, case, or precomposed versus
    decomposed characters compare equal.

    Note: only characters that decompose into a base letter plus combining marks
    are affected.  Letters such as 'ø', 'đ' and 'ł' have no such decomposition
    and are left alone."""
    s = unicodedata.normalize("NFD", s)
    s = s.casefold()
    # casefold can introduce new combining marks (e.g. 'İ' -> 'i' + U+0307),
    # so decompose again before stripping them.
    s = unicodedata.normalize("NFD", s)
    s = "".join(c for c in s if not unicodedata.combining(c))
    return unicodedata.normalize("NFC", s)


# Shared HTTP settings

BASEURL = "https://catalog.fcpl.org"
_delay = 5
HTTP_HEADERS = {
    'Host': urlsplit(BASEURL).netloc,
    'Accept': 'application/json, text/javascript, */*; q=0.01',
    'Connection': 'close',
    'Content-Type': 'application/json; charset=UTF-8'
}


def get_delay():
    """Return the delay, in seconds, used between catalog requests."""
    return _delay


# Call set_delay before creating a session so its retry adapter captures the
# configured value as its backoff factor. Changing it later affects future
# request sleeps but does not reconfigure an existing session's adapter.
def set_delay(seconds):
    """Set the delay, in seconds, used between catalog requests."""
    if seconds < 0:
        raise ValueError("Delay must be zero or greater.")
    global _delay
    _delay = seconds


# Session creation

def create_resilient_session(retries=3, backoff=None):
    """Create a context-manager-compatible session with retries for safe requests."""
    if backoff is None:
        backoff = get_delay()
    retry = Retry(
        total=retries,
        connect=retries,
        read=retries,
        status=retries,
        backoff_factor=backoff,
        status_forcelist=(429, 500, 502, 503, 504),
        respect_retry_after_header=True,
    )
    adapter = HTTPAdapter(max_retries=retry)
    session = requests.Session()
    session.mount("http://", adapter)
    session.mount("https://", adapter)
    return session


# HTTP request helpers


def get_json(s, url, params=None):
    """GET a JSON response with concise errors that omit request URLs."""
    try:
        response = s.get(url, params=params)
        response.raise_for_status()
    except requests.exceptions.HTTPError as exc:
        status = exc.response.status_code if exc.response is not None else "unknown"
        raise RuntimeError(f"GET request failed with HTTP {status}.") from None
    except requests.exceptions.RequestException as exc:
        raise RuntimeError(
            f"GET request failed ({type(exc).__name__})."
        ) from None

    try:
        return response.json()
    except requests.exceptions.JSONDecodeError:
        raise RuntimeError("GET response was not valid JSON.") from None


def get_xml(s, url, params=None):
    """GET and parse an XML response with errors that omit request URLs."""
    try:
        response = s.get(url, params=params)
        response.raise_for_status()
    except requests.exceptions.HTTPError as exc:
        status = exc.response.status_code if exc.response is not None else "unknown"
        raise RuntimeError(f"GET request failed with HTTP {status}.") from None
    except requests.exceptions.RequestException as exc:
        raise RuntimeError(
            f"GET request failed ({type(exc).__name__})."
        ) from None

    try:
        return xmltodict.parse(response.content)
    except Exception:
        raise RuntimeError("GET response was not valid XML.") from None


def post_json(s, url, payload, retries=0, backoff=None):
    """POST JSON and retry transient failures up to ``retries`` times."""
    if backoff is None:
        backoff = get_delay()
    retryable_statuses = {429, 500, 502, 503, 504}
    attempts = 0
    while True:
        try:
            response = s.post(url, json=payload)
        except requests.exceptions.RequestException as exc:
            if attempts >= retries:
                raise RuntimeError(
                    f"POST request failed ({type(exc).__name__})."
                ) from None
        else:
            if response.status_code not in retryable_statuses or attempts >= retries:
                try:
                    response.raise_for_status()
                except requests.exceptions.HTTPError:
                    raise RuntimeError(
                        f"POST request failed with HTTP {response.status_code}."
                    ) from None
                try:
                    return response.json()
                except requests.exceptions.JSONDecodeError:
                    raise RuntimeError("POST response was not valid JSON.") from None
        time.sleep(backoff * (2 ** attempts))
        attempts += 1


# Catalog resource access

def get_resource(s, resource_id):
    url = f"{BASEURL}/resource/{resource_id}"
    response_data = get_json(s, url)
    time.sleep(get_delay())
    return response_data
